commands:
W=$(cd ../clone-work && pwd)/scratch; R=$(pwd); mkdir -p $W/base
cat > $W/legacy_codec_test.go <<'EOF'
package proto

import (
	"testing"

	protov1 "github.com/golang/protobuf/proto"
	"google.golang.org/grpc/encoding"
)

type legacyMsg struct {
	Name string `protobuf:"bytes,1,opt,name=name,proto3" json:"name,omitempty"`
}

func (m *legacyMsg) Reset()         { *m = legacyMsg{} }
func (m *legacyMsg) String() string { return protov1.CompactTextString(m) }
func (*legacyMsg) ProtoMessage()    {}

func TestLegacyV1Message(t *testing.T) {
	c := encoding.GetCodec("proto")
	b, err := c.Marshal(&legacyMsg{Name: "x"})
	t.Logf("Marshal: %v %v", b, err)
	out := &legacyMsg{}
	err = c.Unmarshal([]byte{10, 1, 'x'}, out)
	t.Logf("Unmarshal: %+v %v", out, err)
}
EOF
git show main:encoding/proto/proto.go > $W/base/proto.go
printf '{"Replace":{"%s/encoding/proto/legacy_codec_test.go":"%s/legacy_codec_test.go"}}' $R $W > $W/ov_head.json
printf '{"Replace":{"%s/encoding/proto/legacy_codec_test.go":"%s/legacy_codec_test.go","%s/encoding/proto/proto.go":"%s/base/proto.go"}}' $R $W $R $W > $W/ov_base.json
C=$(cd ../clone-cache && pwd); export GOMODCACHE=$C/gomodcache GOCACHE=$C/gocache GOFLAGS=-mod=readonly GOPROXY=off GOSUMDB=off GOTOOLCHAIN=local
echo HEAD; go test -overlay $W/ov_head.json -run TestLegacyV1Message -v ./encoding/proto/ 2>&1 | grep -E "Marshal|ok|FAIL"
echo BASE; go test -overlay $W/ov_base.json -run TestLegacyV1Message -v ./encoding/proto/ 2>&1 | grep -E "Marshal|ok|FAIL"

W=$(cd ../clone-work && pwd)/scratch; R=$(pwd)
cat > $W/legacy_status_test.go <<'EOF'
package status_test

import (
	"testing"

	protov1 "github.com/golang/protobuf/proto"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

type legacyDetail struct {
	Name string `protobuf:"bytes,1,opt,name=name,proto3" json:"name,omitempty"`
}

func (m *legacyDetail) Reset()         { *m = legacyDetail{} }
func (m *legacyDetail) String() string { return protov1.CompactTextString(m) }
func (*legacyDetail) ProtoMessage()    {}

func init() { protov1.RegisterType((*legacyDetail)(nil), "grpc.scratch.LegacyDetail") }

func TestLegacyDetails(t *testing.T) {
	s, err := status.New(codes.Internal, "x").WithDetails(&legacyDetail{Name: "n"})
	if err != nil {
		t.Fatalf("WithDetails: %v", err)
	}
	for _, d := range s.Details() {
		_, ok := d.(*legacyDetail)
		t.Logf("detail type %T, is *legacyDetail: %v", d, ok)
	}
}
EOF
git show main:internal/status/status.go > $W/base/status.go
printf '{"Replace":{"%s/status/legacy_status_test.go":"%s/legacy_status_test.go"}}' $R $W > $W/ov_shead.json
printf '{"Replace":{"%s/status/legacy_status_test.go":"%s/legacy_status_test.go","%s/internal/status/status.go":"%s/base/status.go"}}' $R $W $R $W > $W/ov_sbase.json
C=$(cd ../clone-cache && pwd); export GOMODCACHE=$C/gomodcache GOCACHE=$C/gocache GOFLAGS=-mod=readonly GOPROXY=off GOSUMDB=off GOTOOLCHAIN=local
echo HEAD; go test -overlay $W/ov_shead.json -run TestLegacyDetails -v ./status/ 2>&1 | grep -E "detail|ok|FAIL|WithDetails"
echo BASE; go test -overlay $W/ov_sbase.json -run TestLegacyDetails -v ./status/ 2>&1 | grep -E "detail|ok|FAIL|WithDetails"
echo CODEC-UNMARSHAL; go test -overlay $W/ov_head.json -run TestLegacyV1Message -v ./encoding/proto/ 2>&1 | grep -i unmarshal
